import * as React from "react"
import { useRender } from "@base-ui/react/use-render"
import { cva, type VariantProps } from "class-variance-authority"
import { ChevronLeft, ChevronRight, MoreHorizontal } from "lucide-react"

import { cn } from "@/lib/utils"
import "./pagination.css"

function Slot({
  children,
  ...props
}: React.PropsWithChildren<Record<string, unknown>>) {
  const valid = React.isValidElement(children)
  return useRender({
    render: valid
      ? (children as React.ReactElement<Record<string, unknown>>)
      : undefined,
    defaultTagName: "a",
    props: valid ? props : { ...props, children },
  })
}

/* ------------------------------------------------------------------ */
/*  CVA                                                                */
/* ------------------------------------------------------------------ */

const paginationLinkVariants = cva(
  "pagination-link inline-flex items-center justify-center rounded-[var(--layout-radius-md)] outline-none transition-colors duration-150",
  {
    variants: {
      size: {
        sm: "pagination-link-sm text-content-caption",
        md: "pagination-link-md text-content-note",
      },
    },
    defaultVariants: { size: "md" },
  }
)

const paginationPrevNextVariants = cva(
  "pagination-prev-next inline-flex items-center gap-[var(--layout-gap-sm)] rounded-[var(--layout-radius-md)] outline-none transition-colors duration-150",
  {
    variants: {
      size: {
        sm: "pagination-prev-next-sm text-content-caption",
        md: "pagination-prev-next-md text-content-note",
      },
    },
    defaultVariants: { size: "md" },
  }
)

/* ------------------------------------------------------------------ */
/*  Pagination                                                         */
/* ------------------------------------------------------------------ */

function Pagination({
  className,
  ...props
}: React.ComponentProps<"nav">) {
  return (
    <nav
      data-slot="pagination"
      aria-label="pagination"
      className={cn("mx-auto flex w-full justify-center", className)}
      {...props}
    />
  )
}

/* ------------------------------------------------------------------ */
/*  PaginationContent                                                  */
/* ------------------------------------------------------------------ */

function PaginationContent({
  className,
  ...props
}: React.ComponentProps<"ul">) {
  return (
    <ul
      data-slot="pagination-content"
      role="list"
      className={cn(
        "flex flex-row items-center gap-[var(--layout-gap-sm)]",
        className
      )}
      {...props}
    />
  )
}

/* ------------------------------------------------------------------ */
/*  PaginationItem                                                     */
/* ------------------------------------------------------------------ */

function PaginationItem({
  className,
  ...props
}: React.ComponentProps<"li">) {
  return (
    <li
      data-slot="pagination-item"
      className={cn(className)}
      {...props}
    />
  )
}

/* ------------------------------------------------------------------ */
/*  PaginationLink                                                     */
/* ------------------------------------------------------------------ */

type PaginationLinkProps = React.ComponentProps<"a"> &
  VariantProps<typeof paginationLinkVariants> & {
    isActive?: boolean
    asChild?: boolean
  }

function PaginationLink({
  asChild,
  isActive = false,
  size,
  className,
  children,
  "aria-label": ariaLabelProp,
  ...props
}: PaginationLinkProps) {
  const Comp = asChild ? Slot : "a"

  // Auto-inject aria-label when children is numeric and no aria-label provided
  const autoLabel =
    !ariaLabelProp &&
    (typeof children === "string" || typeof children === "number")
      ? isActive
        ? `Page ${children}`
        : `Go to page ${children}`
      : ariaLabelProp

  return (
    <Comp
      data-slot="pagination-link"
      data-active={isActive ? "true" : undefined}
      aria-current={isActive ? "page" : undefined}
      aria-label={autoLabel}
      className={cn(paginationLinkVariants({ size }), className)}
      {...props}
    >
      {children}
    </Comp>
  )
}

/* ------------------------------------------------------------------ */
/*  PaginationPrevious                                                 */
/* ------------------------------------------------------------------ */

type PaginationPrevNextProps = React.ComponentProps<"a"> &
  VariantProps<typeof paginationPrevNextVariants> & {
    asChild?: boolean
  }

function PaginationPrevious({
  asChild,
  size,
  className,
  children,
  "aria-label": ariaLabel = "Go to previous page",
  ...props
}: PaginationPrevNextProps) {
  if (asChild) {
    return (
      <Slot
        data-slot="pagination-previous"
        aria-label={ariaLabel}
        className={cn(paginationPrevNextVariants({ size }), className)}
        {...props}
      >
        {children}
      </Slot>
    )
  }

  const label = children === undefined ? "Previous" : children

  return (
    <a
      data-slot="pagination-previous"
      aria-label={ariaLabel}
      className={cn(paginationPrevNextVariants({ size }), className)}
      {...props}
    >
      <ChevronLeft className="size-4" aria-hidden="true" />
      {label !== null && (
        <span className="hidden sm:inline-block">{label}</span>
      )}
    </a>
  )
}

/* ------------------------------------------------------------------ */
/*  PaginationNext                                                     */
/* ------------------------------------------------------------------ */

function PaginationNext({
  asChild,
  size,
  className,
  children,
  "aria-label": ariaLabel = "Go to next page",
  ...props
}: PaginationPrevNextProps) {
  if (asChild) {
    return (
      <Slot
        data-slot="pagination-next"
        aria-label={ariaLabel}
        className={cn(paginationPrevNextVariants({ size }), className)}
        {...props}
      >
        {children}
      </Slot>
    )
  }

  const label = children === undefined ? "Next" : children

  return (
    <a
      data-slot="pagination-next"
      aria-label={ariaLabel}
      className={cn(paginationPrevNextVariants({ size }), className)}
      {...props}
    >
      {label !== null && (
        <span className="hidden sm:inline-block">{label}</span>
      )}
      <ChevronRight className="size-4" aria-hidden="true" />
    </a>
  )
}

/* ------------------------------------------------------------------ */
/*  PaginationStatus                                                   */
/* ------------------------------------------------------------------ */

type PaginationStatusProps = Omit<React.ComponentProps<"li">, "children"> & {
  current: number
  total: number
  format?: (current: number, total: number) => React.ReactNode
}

function PaginationStatus({
  current,
  total,
  format = (c, t) => `Page ${c} of ${t}`,
  className,
  ...props
}: PaginationStatusProps) {
  return (
    <li
      data-slot="pagination-status"
      aria-live="polite"
      className={cn(
        "pagination-status inline-flex items-center px-[var(--layout-padding-sm)] text-content-note sm:hidden",
        className
      )}
      {...props}
    >
      {format(current, total)}
    </li>
  )
}

/* ------------------------------------------------------------------ */
/*  PaginationEllipsis                                                 */
/* ------------------------------------------------------------------ */

function PaginationEllipsis({
  className,
  children,
  ...props
}: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="pagination-ellipsis"
      className={cn(
        "pagination-ellipsis hidden sm:inline-flex h-[var(--layout-size-lg)] w-[var(--layout-size-lg)] items-center justify-center",
        className
      )}
      {...props}
    >
      {children ?? (
        <>
          <MoreHorizontal className="size-4" aria-hidden="true" />
          <span className="sr-only">More pages</span>
        </>
      )}
    </span>
  )
}

/* ------------------------------------------------------------------ */
/*  Exports                                                            */
/* ------------------------------------------------------------------ */

export {
  Pagination,
  PaginationContent,
  PaginationItem,
  PaginationLink,
  PaginationPrevious,
  PaginationNext,
  PaginationStatus,
  PaginationEllipsis,
  paginationLinkVariants,
  paginationPrevNextVariants,
}

/* ================================================================
 * PAGINATION — Token-based theming
 * ================================================================ */

/* Link — sizing */
.pagination-link-sm {
  height: var(--layout-size-md);
  min-width: var(--layout-size-md);
  padding-inline: var(--layout-padding-xs);
}

.pagination-link-md {
  height: var(--layout-size-lg);
  min-width: var(--layout-size-lg);
  padding-inline: var(--layout-padding-sm);
}

/* Link — default state */
.pagination-link {
  color: var(--text-base-strong);
  background-color: transparent;
  cursor: pointer;
  font-weight: var(--font-weight-regular);
}

.pagination-link:hover {
  background-color: var(--background-neutral-faint-hover);
}

.pagination-link:focus-visible {
  box-shadow:
    0 0 0 2px var(--background-base),
    0 0 0 4px var(--border-selected);
}

/* Link — active (current page) — neutral subtle, not brand */
.pagination-link[data-active="true"] {
  background-color: var(--background-neutral-faint-pressed);
  font-weight: var(--font-weight-accent);
  cursor: default;
}

.pagination-link[data-active="true"]:hover {
  background-color: var(--background-neutral-faint-pressed);
}

/* Link — disabled */
.pagination-link[aria-disabled="true"],
.pagination-link[data-disabled="true"] {
  color: var(--text-disabled);
  pointer-events: none;
  cursor: default;
}

/* Prev/Next — sizing */
.pagination-prev-next-sm {
  height: var(--layout-size-md);
  padding-inline: var(--layout-padding-xs);
}

.pagination-prev-next-md {
  height: var(--layout-size-lg);
  padding-inline: var(--layout-padding-sm);
}

/* Prev/Next — default state */
.pagination-prev-next {
  color: var(--text-base-strong);
  background-color: transparent;
  cursor: pointer;
  font-weight: var(--font-weight-regular);
}

.pagination-prev-next:hover {
  background-color: var(--background-neutral-faint-hover);
}

.pagination-prev-next:focus-visible {
  box-shadow:
    0 0 0 2px var(--background-base),
    0 0 0 4px var(--border-selected);
}

/* Prev/Next — disabled */
.pagination-prev-next[aria-disabled="true"],
.pagination-prev-next[data-disabled="true"] {
  color: var(--text-disabled);
  pointer-events: none;
  cursor: default;
}

/* Status (mobile only) */
.pagination-status {
  color: var(--text-base-moderate);
}

/* Ellipsis */
.pagination-ellipsis {
  color: var(--icon-neutral-moderate);
}

/* Reduced motion — slow, don't remove (Lyse convention) */
@media (prefers-reduced-motion: reduce) {
  .pagination-link,
  .pagination-prev-next {
    transition-duration: 0.01ms;
  }
}
